 UNION ALL SELECT 'catalog_helpers_unchanged',NOT EXISTS(SELECT 1 FROM helpers h LEFT JOIN (pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace AND n.nspname='public') ON p.proname=h.name WHERE p.oid IS NULL OR md5(regexp_replace(p.prosrc,'\s+','','g'))<>h.hash OR p.prosecdef<>h.definer OR pg_get_userbyid(p.proowner)<>'postgres' OR NOT coalesce(p.proconfig @> ARRAY['search_path=""'],false) OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE'))
